import 'package:flutter/material.dart';
import '../../app/theme/app_colors.dart';
class PrimaryButton extends StatelessWidget { final String label; final VoidCallback? onPressed; final bool loading; const PrimaryButton({super.key, required this.label, this.onPressed, this.loading = false}); @override Widget build(BuildContext context) => SizedBox(width: double.infinity, height: 52, child: ElevatedButton(onPressed: loading ? null : onPressed, style: ElevatedButton.styleFrom(backgroundColor: AppColors.accent, foregroundColor: Colors.black, disabledBackgroundColor: AppColors.border, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))), child: loading ? const SizedBox(width:20,height:20,child:CircularProgressIndicator(strokeWidth:2,color:Colors.black)) : Text(label, style: const TextStyle(fontWeight: FontWeight.w700)))); }
